# Surah At-Tawbah (chapter 9) — part 3: ayat 21-30 (IDs 1256-1265)
SURAH = 9

ENTRIES = {
1256: (
"ان — کو ان کا — رب — اپنی طرف سے — رحمت — اور خوشنودی — اور — ایسی جنتوں — کی خوش خبری سناتا ہے — جن میں — ان کے لیے — ہمیشہ کی نعمت — ہے",
"""۱۔ مؤمنوں کا انعام — رحمت، خوشنودی اور جنت۔
۲۔ ’’يُبَشِّرُهُمْ رَبُّهُم بِرَحْمَۃٍ مِّنْهُ وَرِضْوَانٍ وَجَنَّاتٍ لَّهُمْ فِيهَا نَعِيمٌ مُّقِيمٌ‘‘ — ان — کو ان کا — رب — اپنی طرف سے — رحمت — اور خوشنودی — اور — ایسی جنتوں — کی خوش خبری سناتا ہے — جن میں — ان کے لیے — ہمیشہ کی نعمت — ہے — یعنی اللہ — مؤمنوں کو — رحمت، رضوان اور — ہمیشہ کی نعمت والی — جنتوں کی بشارت — دیتا ہے۔
۳۔ عملی سبق: مؤمن کی — امید — ہمیشہ — اللہ کی رحمت اور خوشنودی ہے۔"""
),
1257: (
"وہ — ان میں — ہمیشہ رہیں گے — بے شک — اللہ — کے پاس — عظیم اجر — ہے",
"""۱۔ جنت — ہمیشہ کے لیے۔
۲۔ ’’خَالِدِينَ فِيهَا أَبَدًا إِنَّ اللَّهَ عِندَهُ أَجْرٌ عَظِيمٌ‘‘ — وہ — ان میں — ہمیشہ رہیں گے — بے شک — اللہ — کے پاس — عظیم اجر — ہے — یعنی مؤمن — ہمیشہ — جنت میں — رہیں گے — اور اللہ کے پاس — عظیم اجر — ہے۔
۳۔ عملی سبق: جنت — ہمیشہ کی زندگی — ہے۔"""
),
1258: (
"اے ایمان والو — اپنے باپوں — اور اپنے بھائیوں — کو — کارساز مت بناؤ — اگر — انہوں نے ایمان کے مقابلے میں — کفر — کو — ترجیح دی — اور — تم — میں سے — جو — انہیں دوست بنائے — تو یہ لوگ — ظالم ہیں",
"""۱۔ کافر باپ اور بھائی — بھی — دوست نہیں بن سکتے۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَتَّخِذُوا آبَاءَكُمْ وَإِخْوَانَكُمْ أَوْلِيَاءَ إِنِ اسْتَحَبُّوا الْكُفْرَ عَلَى الْإِيمَانِ وَمَن يَتَوَلَّهُم مِّنكُمْ فَأُولَٰئِكَ هُمُ الظَّالِمُونَ‘‘ — اے ایمان والو — اپنے باپوں — اور اپنے بھائیوں — کو — کارساز مت بناؤ — اگر — انہوں نے ایمان کے مقابلے میں — کفر — کو — ترجیح دی — اور — تم — میں سے — جو — انہیں دوست بنائے — تو یہ لوگ — ظالم ہیں — یعنی کافر قرابتداروں سے — دوستی — جائز نہیں۔
۳۔ عملی سبق: ایمان — قرابتداری — سے اوپر ہے۔"""
),
1259: (
"کہدو — اگر — تمہارے باپ — تمہارے بیٹے — تمہارے بھائی — تمہاری بیویاں — تمہارے قبیلے — اور — وہ مال — جو تم نے — کمائے — اور — وہ تجارت — جس — کی کساد کے تمہیں — ڈر لگتا ہے — اور — وہ گھر — جن کو تم — پسند کرتے ہو — اللہ — اس کے رسولؐ — اور — اللہ کی راہ میں — جہاد — سے زیادہ محبوب ہوں — تو — انتظار کرو — یہاں تک کہ — اللہ — اپنا حکم — لا دے — اور — اللہ — فاسقوں کو — ہدایت نہیں دیتا",
"""۱۔ اگر مال و اہل — اللہ و رسولؐ سے بڑھ کر — محبوب ہوں — تو — انتظار کرو اللہ کے حکم کا۔
۲۔ ’’قُلْ إِن كَانَ آبَاؤُكُمْ وَأَبْنَاؤُكُمْ وَإِخْوَانُكُمْ وَأَزْوَاجُكُمْ وَعَشِيرَتُكُمْ وَأَمْوَالٌ اقْتَرَفْتُمُوهَا وَتِجَارَۃٌ تَخْشَوْنَ كَسَادَهَا وَمَسَاكِنُ تَرْضَوْنَهَا أَحَبَّ إِلَيْكُم مِّنَ اللَّهِ وَرَسُولِهِ وَجِهَادٍ فِي سَبِيلِهِ فَتَرَبَّصُوا حَتَّىٰ يَأْتِيَ اللَّهُ بِأَمْرِهِ وَاللَّهُ لَا يَهْدِي الْقَوْمَ الْفَاسِقِينَ‘‘ — کہدو — اگر — تمہارے باپ — تمہارے بیٹے — تمہارے بھائی — تمہاری بیویاں — تمہارے قبیلے — اور — وہ مال — جو تم نے — کمائے — اور — وہ تجارت — جس — کی کساد کے تمہیں — ڈر لگتا ہے — اور — وہ گھر — جن کو تم — پسند کرتے ہو — اللہ — اس کے رسولؐ — اور — اللہ کی راہ میں — جہاد — سے زیادہ محبوب ہوں — تو — انتظار کرو — یہاں تک کہ — اللہ — اپنا حکم — لا دے — اور — اللہ — فاسقوں کو — ہدایت نہیں دیتا — یعنی اللہ، رسولؐ اور جہاد کو — سب سے زیادہ محبوب بنانا — ایمان کی شرط ہے۔
۳۔ عملی سبق: اللہ، رسولؐ اور جہاد — سب سے بلند درجے — رکھو۔"""
),
1260: (
"بے شک — اللہ — نے — تمہیں — بہت سی جگہوں پر — مدد کی — اور — حنین کے دن — جب — تمہاری — کثرت — نے — تمہیں مغرور کیا — تو — تمہاری — کثرت — نے — کوئی فائدہ نہیں دیا — اور — زمین — اپنی کشادگی کے باوجود — تمہارے لیے — تنگ ہو گئی — پھر — تم — پیٹھ — موڑ کر بھاگ کھڑے ہوئے",
"""۱۔ حنین — کثرت کی آزمائش — اور عارضی شکست۔
۲۔ ’’لَقَدْ نَصَرَكُمُ اللَّهُ فِي مَوَاطِنَ كَثِيرَۃٍ وَيَوْمَ حُنَيْنٍ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنكُمْ شَيْئًا وَضَاقَتْ عَلَيْكُمُ الْأَرْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّيْتُم مُّدْبِرِينَ‘‘ — بے شک — اللہ — نے — تمہیں — بہت سی جگہوں پر — مدد کی — اور — حنین کے دن — جب — تمہاری — کثرت — نے — تمہیں مغرور کیا — تو — تمہاری — کثرت — نے — کوئی فائدہ نہیں دیا — اور — زمین — اپنی کشادگی کے باوجود — تمہارے لیے — تنگ ہو گئی — پھر — تم — پیٹھ — موڑ کر بھاگ کھڑے ہوئے — یعنی حنین میں — مسلمان — تعداد میں زیادہ تھے — مگر — اللہ کی مدد — کے بغیر — وہ — ناکام ہو گئے۔
۳۔ عملی سبق: کثرت — کبھی فائدہ نہیں دیتی؛ اللہ کی مدد — ضروری ہے۔"""
),
1261: (
"پھر — اللہ — نے — اپنا سکون — اپنے رسولؐ پر — اور مؤمنوں پر — اتارا — اور — ایسے لشکر اتارے جو — تمہیں نظر نہیں آتے — اور ـ کافروں کو — عذاب دیا — اور — یہ — کافروں کی سزا ہے",
"""۱۔ حنین میں — اللہ کی غیبی مدد — سکون اور فرشتے۔
۲۔ ’’ثُمَّ أَنزَلَ اللَّهُ سَكِينَتَهُ عَلَىٰ رَسُولِهِ وَعَلَى الْمُؤْمِنِينَ وَأَنزَلَ جُنُودًا لَّمْ تَرَوْهَا وَعَذَّبَ الَّذِينَ كَفَرُوا وَذَٰلِكَ جَزَاءُ الْكَافِرِينَ‘‘ — پھر — اللہ — نے — اپنا سکون — اپنے رسولؐ پر — اور مؤمنوں پر — اتارا — اور — ایسے لشکر اتارے جو — تمہیں نظر نہیں آتے — اور ـ کافروں کو — عذاب دیا — اور — یہ — کافروں کی سزا ہے — یعنی حنین میں — اللہ نے — سکون اور فرشتے — بھیج کر — فتح — دی۔
۳۔ عملی سبق: مدد — صرف اللہ کی طرف سے ہے؛ کثرت پر فخر نہ کرو۔"""
),
1262: (
"پھر — اللہ — اس — کے بعد — مکہ میں — جس کی چاہے — توبہ — قبول کرتا ہے — اور — اللہ — بخشنے والا مہربان ہے",
"""۱۔ حنین کے بعد — اللہ کی رحمت کا دروازہ کھلا۔
۲۔ ’’ثُمَّ يَتُوبُ اللَّهُ مِن بَعْدِ ذَٰلِكَ عَلَىٰ مَن يَشَاءُ وَاللَّهُ غَفُورٌ رَّحِيمٌ‘‘ — پھر — اللہ — اس — کے بعد — مکہ میں — جس کی چاہے — توبہ — قبول کرتا ہے — اور — اللہ — بخشنے والا مہربان ہے — یعنی شکست کے بعد — اللہ — جس کی چاہے — توبہ قبول کرتا ہے۔
۳۔ عملی سبق: توبہ — ہمیشہ — ممکن ہے۔"""
),
1263: (
"اے ایمان والو — بے شک — مشرک — نجس ہیں — پس — وہ — اس — سال کے بعد — مسجد الحرام — کے قریب نہ آئیں — اور — اگر — تمہیں — افلاس کا خوف ہو — تو — اللہ — تمہیں — عنقریب اپنے فضل — سے — بے نیاز کر دے گا — اگر وہ چاہے — بے شک — اللہ — جاننے والا حکمت والا ہے",
"""۱۔ مشرک — مسجد الحرام کے قریب — نہیں آ سکتے۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْمُشْرِكُونَ نَجَسٌ فَلَا يَقْرَبُوا الْمَسْجِدَ الْحَرَامَ بَعْدَ عَامِهِمْ هَٰذَا وَإِنْ خِفْتُمْ عَيْلَۃً فَسَوْفَ يُغْنِيكُمُ اللَّهُ مِن فَضْلِهِ إِن شَاءَ إِنَّ اللَّهَ عَلِيمٌ حَكِيمٌ‘‘ — اے ایمان والو — بے شک — مشرک — نجس ہیں — پس — وہ — اس — سال کے بعد — مسجد الحرام — کے قریب نہ آئیں — اور — اگر — تمہیں — افلاس کا خوف ہو — تو — اللہ — تمہیں — عنقریب اپنے فضل — سے — بے نیاز کر دے گا — اگر وہ چاہے — بے شک — اللہ — جاننے والا حکمت والا ہے — یعنی مشرک — مسجد الحرام میں — داخل نہیں ہو سکتے۔
۳۔ عملی سبق: مسجد الحرام — صرف مؤمنوں کے لیے ہے۔"""
),
1264: (
"ان لوگوں سے لڑو — جو — نہ اللہ پر — اور نہ — آخرت کے دن — پر ایمان لاتے — اور نہ — ان — چیزوں کو حرام سمجھتے ہیں جنہیں — اللہ اور اس کے رسولؐ — نے حرام کیا ہے — اور — نہ حق کے دین — کو اپنا دین بناتے ہیں — ان — میں سے — جو — اہلِ کتاب ہیں — یہاں تک کہ — وہ — جزیہ ادا کریں — اپنے ہاتھ سے — ذلت کے ساتھ",
"""۱۔ اہلِ کتاب سے — جزیہ کے ذریعے — امن کا معاہدہ۔
۲۔ ’’قَاتِلُوا الَّذِينَ لَا يُؤْمِنُونَ بِاللَّهِ وَلَا بِالْيَوْمِ الْآخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ اللَّهُ وَرَسُولُهُ وَلَا يَدِينُونَ دِينَ الْحَقِّ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ حَتَّىٰ يُعْطُوا الْجِزْيَۃَ عَن يَدٍ وَهُمْ صَاغِرُونَ‘‘ — ان لوگوں سے لڑو — جو — نہ اللہ پر — اور نہ — آخرت کے دن — پر ایمان لاتے — اور نہ — ان — چیزوں کو حرام سمجھتے ہیں جنہیں — اللہ اور اس کے رسولؐ — نے حرام کیا ہے — اور — نہ حق کے دین — کو اپنا دین بناتے ہیں — ان — میں سے — جو — اہلِ کتاب ہیں — یہاں تک کہ — وہ — جزیہ ادا کریں — اپنے ہاتھ سے — ذلت کے ساتھ — یعنی اہلِ کتاب — جزیہ — دے کر — امن — حاصل کر سکتے ہیں۔
۳۔ عملی سبق: جزیہ — امن کا — ایک اسلامی — معاہدہ ہے۔"""
),
1265: (
"اور — یہود — کہتے ہیں — عزیر — اللہ کے بیٹے ہیں — اور — نصاریٰ — کہتے ہیں — مسیح — اللہ کے بیٹے ہیں — یہ — ان کے — منہ — کی بات ہے — وہ — ان — کی مانند — کہتے ہیں — جو — پہلے — کفر کر چکے تھے — اللہ انہیں — ہلاک کرے — کہاں سے — دھوکا — کھا جاتے ہیں",
"""۱۔ یہود و نصاریٰ — جھوٹے دعویٰ — بس زبان — کی بات ہے۔
۲۔ ’’وَقَالَتِ الْيَهُودُ عُزَيْرٌ ابْنُ اللَّهِ وَقَالَتِ النَّصَارَى الْمَسِيحُ ابْنُ اللَّهِ ذَٰلِكَ قَوْلُهُم بِأَفْوَاهِهِمْ يُضَاهِئُونَ قَوْلَ الَّذِينَ كَفَرُوا مِن قَبْلُ قَاتَلَهُمُ اللَّهُ أَنَّىٰ يُؤْفَكُونَ‘‘ — اور — یہود — کہتے ہیں — عزیر — اللہ کے بیٹے ہیں — اور — نصاریٰ — کہتے ہیں — مسیح — اللہ کے بیٹے ہیں — یہ — ان کے — منہ — کی بات ہے — وہ — ان — کی مانند — کہتے ہیں — جو — پہلے — کفر کر چکے تھے — اللہ انہیں — ہلاک کرے — کہاں سے — دھوکا — کھا جاتے ہیں — یعنی عزیر اور مسیح — دونوں — اللہ کے نبی — تھے؛ — بیٹا — ہونے کا دعویٰ — سراسر جھوٹ ہے۔
۳۔ عملی سبق: توحید — سب سے بڑی حقیقت ہے؛ کسی کو اللہ کا بیٹا نہ کہو۔"""
),
}
